t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]
def comps_of(gi):
    H,W=len(gi),len(gi[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for r in range(H):
        for c in range(W):
            if gi[r][c] and not seen[r][c]:
                st=[(r,c)]; seen[r][c]=True; cl=[]
                while st:
                    a,b=st.pop(); cl.append((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            x,y=a+da,b+db
                            if 0<=x<H and 0<=y<W and gi[x][y]==gi[r][c] and not seen[x][y]:
                                seen[x][y]=True; st.append((x,y))
                out.append((gi[r][c],cl))
    return out
def solve(gi):
    cs=comps_of(gi); cs.sort(key=lambda co:min(b for _,b in co[1]))
    res=[[0]*len(gi[0]) for _ in range(len(gi))]
    br=(-1,-1)  # last piece's actual bottom-right cell
    for k,(col,cells) in enumerate(cs):
        rmax=max(a for a,_ in cells); cmax=max(b for _,b in cells)
        s=frozenset(cells) if k==len(cs)-1 else {(a,b) for a,b in cells if not(a==rmax and b==cmax)}
        tl=(br[0]+1, br[1]+1) if k>0 else (0,0)
        for a,b in s:
            rr,cc=tl[0]+(a-min(x for x,_ in cells)), tl[1]+(b-min(y for _,y in cells))
            res[rr][cc]=col
        br=(rmax,cmax)
    return res
print(solve(G['Demo pair 1 input'])==G['Demo pair 1 output'], solve(G['Demo pair 2 input'])==G['Demo pair 2 output'])

