        rmin=min(a for a,_ in cells); cmin=min(b for _,b in cells)
        h=max(a for a,_ in cells)-rmin+1; w=max(b for _,b in cells)-cmin+1
        s={(a-rmin,b-cmin) for a,b in cells if k==len(cs)-1 or (a-rmin<b-h or True)}
        # drop BR of bbox except last piece
        s={(a-rmin,b-cmin) for a,b in cells if not(k<len(cs)-1 and a-rmin==h-1 and b-cmin==w-1)}
        cands=[]
        for tr in range(h):
            for tc in range(w):
                if (tr==0 and tc==0 and k>0): continue
                curset={(tr+a,t0+tc+b) for t0,t1 in [(0,0)] for a,b in s} if False else {(tr+a,tc+b) for a,b in s}
                if curset & occ: continue
                cnt=sum(1 for a,b in s for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)] if (tr+a+dr,tc+b+dc) in occ)
                cands.append((cnt,tr,tc,curset))
        if k==0:
            best=(0,0,0,frozenset({(a,b) for a,b in s}))
            for rr,cc,cs0 in [(0,0,[(a,b) for a,b in s])]: pass
            best=(0,0,0,{(a,b) for a,b in s})
            for tr in range(h):
                for tc in range(w):
                    curset={(tr+a,tc+b) for a,b in s}
                    if curset & occ: continue
                    cnt=sum(1 for a,b in s for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)] if (tr+a+dr,tc+b+dc) in occ)
                    if cnt>best[0] or (cnt==best[0] and (tr,tc)>best[1:3]): best=(cnt,tr,tc,curset)
        else:
            best=max(cands,key=lambda z:(z[0],-z[1],-z[2]))
        curset=best[3]
        for a,b in curset: res[a][b]=col
        occ|=curset
        prev_br=(max(x for x,_ in curset), max(y for _,y in curset))
    return res
