def solveA(gi, overlap='last'):
    H,W=len(gi),len(gi[0]); res=[[0]*W for _ in range(H)]
    comps=comps_of(gi); comps.sort(key=lambda co:min(b for _,b in co[1]))
    tl=(0,0)
    for k,(col,cells) in enumerate(comps):
        rmin=min(a for a,_ in cells); cmin=min(b for _,b in cells)
        h=max(a for a,_ in cells)-rmin+1; w=max(b for _,b in cells)-cmin+1
        s={(a-rmin,b-cmin) for a,b in cells}
        if k<len(comps)-1: s.discard((h-1,w-1))
        cur={(tl[0]+a,tl[1]+b) for a,b in s}
        for rr,cc in sorted(cur):
            if (rr,cc) not in occ or overlap=='last': res[rr][cc]=col
        occ|=cur
        prev_max=((max(a for a,_ in s)+tl[0]), (max(b for _,b in s)+tl[1]))
